def _moments(q):
    """normalized rational profile moments: returns (qmax, M2, M3)
    for a nonnegative rational vector q with sum q == 1."""
    q = [_Fr(v) for v in q]
    assert sum(q) == 1 and all(v >= 0 for v in q)
    return max(q), sum(v * v for v in q), sum(v ** 3 for v in q)


def _interp_ok(q, wrong="none"):
    """the r324 S0 interpolation on a normalized rational profile:
    M_3 <= qmax x M_2 and M_2 <= qmax (pure algebra: q_j^3 <= qmax
    q_j^2 and q_j^2 <= qmax q_j termwise).  wrong='rev3' asserts
    qmax x M_2 <= M_3, wrong='rev2' asserts qmax <= M_2 -- both
    must FAIL on spread witnesses."""
    qmax, m2, m3 = _moments(q)
    if wrong == "rev3":
        return qmax * m2 <= m3
    if wrong == "rev2":
        return qmax <= m2
    return m3 <= qmax * m2 and m2 <= qmax


def _fa_identity(m, ell, qmax, medloc, wrong="none"):
    """the r324 S0 identity F_A x B x log m == m x q_max on a
    rational toy with the rational log stand-in ell: F_A = qmax /
    medloc (rank-local normalization), B = medloc x m / ell (the
    r321 source-pure baseline) -- the identity is constructional;
    PhiH1 = (F_A B)^2 == (m qmax / ell)^2.  wrong='gauge' uses the
    dropped-gauge B' = medloc x m (no /ell): must FAIL whenever
    ell != 1."""
    m, ell, qmax, medloc = _Fr(m), _Fr(ell), _Fr(qmax), _Fr(medloc)
    fa = qmax / medloc
    b = medloc * m if wrong == "gauge" else medloc * m / ell
    ident = (fa * b * ell == m * qmax)
    phih1 = (fa * (medloc * m / ell)) ** 2 == (m * qmax / ell) ** 2
    return ident and phih1


def _interp_improves(q, m, ell):
    """the S0 improvement of the r321 bracket upper side on a
    rational toy: rho_2 = m^2 M_3 / ell^2 <= PhiH1 x (M_2/qmax)
    <= PhiH1 with M_2/qmax <= 1 -- all exact."""
    qmax, m2, m3 = _moments(q)
    m, ell = _Fr(m), _Fr(ell)
    rho2 = m * m * m3 / (ell * ell)
    phih1 = (m * qmax / ell) ** 2
    return (rho2 <= phih1 * (m2 / qmax) <= phih1
            and m2 / qmax <= 1)


# --------- the r327 group ledger on the sealed rational toy
# --------- (block j*: group A = atoms (3, 2) at one position,
# --------- group B = atom (1); block 1: atom (1))
def _group_ledger(groups_by_block):
    """per-block group ledger: for each block a tuple of groups,
    each group a tuple of rational atom values.  Returns
    (x_blocks, L, partition_ok, l1_ok) where x_j = sum of group
    sums G1_g, gabs_g = sum of |atoms|, partition sum_g gabs ==
    A1_j and the L1 recomposition sum_j |sum_g G1_g| == L."""
    xs, part_ok = [], True
    for groups in groups_by_block:
        g1s = [sum(_Fr(a) for a in g) for g in groups]
        gabs = [sum(abs(_Fr(a)) for a in g) for g in groups]
        a1 = sum(abs(_Fr(a)) for g in groups for a in g)
        part_ok = part_ok and (sum(gabs) == a1)
        xs.append(sum(g1s))
    L = sum(abs(x) for x in xs)
    l1_ok = (sum(abs(x) for x in xs) == L)
    return xs, L, part_ok, l1_ok


def _two_ancestor_ok(group, vmax, mult_cap=2):
    """the r327 two-ancestor bound gabs_g <= mult_cap x vmax,
    exact."""
    gabs = sum(abs(_Fr(a)) for a in group)
    return gabs <= mult_cap * _Fr(vmax)


def _mutant_group_drop(g1s):
    """the r327 e1 mutant: an L1 'recomposition' that drops the
    last group -- must break by exactly the dropped |G1|."""
    g1s = [_Fr(v) for v in g1s]
    return sum(g1s[:-1])


def _mutant_wrong_window_max(atoms):
    """the r327 e2 mutant: the 'window maximum' on the truncated
    atom set (global max dropped)."""
    av = sorted(abs(_Fr(a)) for a in atoms)
    return av[-2]


# --------- the r325 onset toy (exact rational tent-window reads):
# --------- grid element n_g = 4, D_0 = 1/4, x = (1, 2, -1, 1);
# --------- autocorrelation a_d = D_0 sum_i x_i x_{i+d} (a_d = 0
# --------- for d >= n_g -- the closing zero knot); F = the even
# --------- piecewise-linear interpolant with knots d x D_0;
# --------- rational atoms (position, mass) on and off the grid.
_TOY_NG = 4
_TOY_D0 = _Fr(1, 4)
_TOY_X = (_Fr(1), _Fr(2), _Fr(-1), _Fr(1))
_TOY_ATOMS = ((_Fr(1, 8), _Fr(2)), (_Fr(7, 16), _Fr(3)),
              (_Fr(15, 16), _Fr(5)), (_Fr(9, 8), _Fr(1)))


def _toy_acf(d):
    if d >= _TOY_NG:
        return _Fr(0)
    return _TOY_D0 * sum(_TOY_X[i] * _TOY_X[i + d]
                         for i in range(_TOY_NG - d))


def _toy_F(u):
    """the exact even piecewise-linear interpolant at rational u
    (knots d x D_0; zero beyond the support n_g x D_0)."""
    u = abs(_Fr(u))
    t = u / _TOY_D0
    d = int(t)          # exact floor for nonnegative rationals
    frac = t - d
    return _toy_acf(d) + frac * (_toy_acf(d + 1) - _toy_acf(d))


def _toy_atom_sum():
    """the exact reference: -L_cat(F) convention dropped (sign
    irrelevant for the stabilization statement) -- the plain atom
    sum sum_n mu_n F(u_n), exact."""
    return sum(mu * _toy_F(u) for u, mu in _TOY_ATOMS)


def _toy_read(alpha, D, nearest=False):
    """the tent-window read at anchor alpha on the dyadic mesh D
    (native D_0 or a refinement): the window carries M = 2 alpha/D
    lags (lags 0..M-1); an atom at u in mesh cell d = floor(u/D)
    contributes its interpolated mass ONLY if both tent lags d and
    d + 1 are inside the window (d + 1 <= M - 1) -- the T115 tent
    assembly modeled exactly.  nearest=True is the r325 m2-class
    mutant: the atom mass is misplaced onto the nearest grid knot
    (nearest-neighbour read instead of the linear-interpolation
    read)."""
    alpha, D = _Fr(alpha), _Fr(D)
    M = int(2 * alpha / D)          # exact for dyadic D, rational alpha
    total = _Fr(0)
    for u, mu in _TOY_ATOMS:
        t = u / D
        d = int(t)
        if d + 1 > M - 1:
            continue
        if nearest:
            knot = d if (t - d) <= _Fr(1, 2) else d + 1
            total += mu * _toy_F(knot * D)
        else:
            total += mu * _toy_F(u)
    return total


# --------- the m_0* solver (the r324 S3 rule rebuilt verbatim:
# --------- log-space multiplicative grid) and its mutants
_CRIT = 0.224


def _m0_log10(C, e, crit=_CRIT):
    """the r324 log-space solve of m^{crit - e} >= C log m: t =
    ln m on the multiplicative grid t *= 1.02 from ln 73; a finite
    root exists iff crit - e > 0.  Returns log10(m_0*) or None.
    crit defaults to the sealed r324 bar 0.224 (atom-level need
    0.888); the audit-B chain-honest bar 2 x (1 - 908/1002) is
    passed explicitly in S0-T5d."""
    if crit - e <= 0.0:
        return None
    t = math.log(73.0)
    while t < 1e7:
        if t * (crit - e) >= math.log(C) + math.log(t):
            return t / math.log(10.0)
        t *= 1.02
    return None


def _m0_linear_mutant(C, e):
    """the DISCLOSED r324 pre-freeze calibration bug rebuilt: the
    linear-space search capped at 10^18 -- misses the astronomical
    root (returns None at the record parameters)."""
    if _CRIT - e <= 0.0:
        return None
    m = 73.0
    while m < 1e18:
        if m ** (_CRIT - e) >= C * math.log(m):
            return math.log10(m)
        m *= 2.0
    return None


