def mutant_groups_overlap(n):
    """e4 MUST-FAIL MUTANT: a three-thirds split whose neighbor
    groups share EXACTLY one rank -- the disjointness ward must
    measure intersection >= 1 on the mutant and 0/0/0 on the
    sealed qq_groups."""
    k = int(n) // 3
