    if brk:
        return "RECOMP_BREAK"
    if lam_go:
        return "LAMBDA_PAIR_CAP_GO"
    if bal_go:
        return "BALANCE_CAP_GO"
    if unbounded:
        return "HEAVY_GROUP_UNBOUNDED"
    return "CAP_PARTIAL"


